 @Test void operatorScopeAndRevokedMembershipProtectDetailEventsInputsAndArtifacts(){var run=create(UUID.randomUUID().toString()).runId();UUID submission=service.requireRun(OPERATOR,run);UUID task=db.queryForObject("SELECT manual_task_id FROM grading_submissions WHERE id=?",UUID.class,submission);assertThat(service.image(auth,run,task,true).bytes()).isNotEmpty();assertThatThrownBy(()->service.detail(authentication(other),run)).extracting("status").isEqualTo(403);assertThatThrownBy(()->service.image(auth,run,UUID.randomUUID(),true)).extracting("status").isEqualTo(404);assertThatThrownBy(()->service.artifact(auth,run,UUID.randomUUID())).extracting("status").isEqualTo(404);db.update("UPDATE school_experts SET enabled=false WHERE user_id=?",OPERATOR);assertThatThrownBy(()->service.detail(auth,run)).extracting("status").isEqualTo(403);assertThatThrownBy(()->service.events(auth,run,0,100)).extracting("status").isEqualTo(403);assertThatThrownBy(()->service.image(auth,run,task,true)).extracting("status").isEqualTo(403);}
 record Login(String session,String csrf){}
 String cookie(HttpHeaders headers,String name){return headers.getOrEmpty("Set-Cookie").stream().filter(c->c.startsWith(name+"=")).map(c->c.substring(name.length()+1,c.indexOf(';'))).findFirst().orElse(null);}
 HttpHeaders headers(Login login,boolean csrf){var h=new HttpHeaders();h.set("Cookie",(login.session==null?"":"SESSION="+login.session+"; ")+(login.csrf==null?"":"XSRF-TOKEN="+login.csrf));if(csrf&&login.csrf!=null)h.set("X-XSRF-TOKEN",login.csrf);return h;}
 Login login(){var initial=rest.getForEntity("/api/auth/csrf",String.class);String token=cookie(initial.getHeaders(),"XSRF-TOKEN");var h=headers(new Login(null,token),true);h.setContentType(MediaType.APPLICATION_JSON);var response=rest.exchange("/api/auth/login",HttpMethod.POST,new HttpEntity<>(json.write(Map.of("email","operator@example.test","password","test-password-secure")),h),String.class);assertThat(response.getStatusCode().value()).isEqualTo(200);String session=cookie(response.getHeaders(),"SESSION");var fresh=rest.exchange("/api/auth/csrf",HttpMethod.GET,new HttpEntity<>(headers(new Login(session,null),false)),String.class);return new Login(session,cookie(fresh.getHeaders(),"XSRF-TOKEN"));}
 ResponseEntity<String> post(Login login,String path,byte[] task,List<byte[]> solutions,boolean csrf){MultiValueMap<String,Object> parts=new LinkedMultiValueMap<>();parts.add("task_number","16");parts.add("task_image",part(task,"task.png"));for(byte[] bytes:solutions)parts.add("solution_images",part(bytes,"solution.png"));var h=headers(login,csrf);h.setContentType(MediaType.MULTIPART_FORM_DATA);h.set("Idempotency-Key",UUID.randomUUID().toString());return rest.exchange(path,HttpMethod.POST,new HttpEntity<>(parts,h),String.class);}
 HttpEntity<ByteArrayResource> part(byte[] bytes,String name){var h=new HttpHeaders();h.setContentType(MediaType.IMAGE_PNG);return new HttpEntity<>(new ByteArrayResource(bytes){public String getFilename(){return name;}},h);}
 @Test void manualMultipartAcceptsFortyMiBAndRejectsOversizedFileAndCsrf(){
    Login login=login();byte[] padded=Arrays.copyOf(image,8*1024*1024);
    var accepted=post(login,"/api/local-demo/runs/manual",padded,List.of(padded,padded,padded,padded),true);
    assertThat(accepted.getStatusCode().value()).withFailMessage(accepted.getBody()).isEqualTo(202);
    assertThat(accepted.getHeaders().getFirst("Cache-Control")).isEqualTo("private, no-store");
    var body=json.read(accepted.getBody());for(String key:List.of("assignmentId","workId","errorCode","aiResult"))assertThat(body.get(key).isNull()).isTrue();assertThat(body.path("task").get("statement").isNull()).isTrue();assertThat(body.path("observer").get("expiresAt").isNull()).isTrue();assertThat(body.path("images").get(0).get("sourceDocumentId").isNull()).isTrue();
    assertThat(post(login,"/api/local-demo/runs/manual",image,List.of(image),false).getStatusCode().value()).isEqualTo(403);
    var oversized=post(login,"/api/local-demo/runs/manual",Arrays.copyOf(image,8*1024*1024+1),List.of(image),true);
    assertThat(oversized.getStatusCode().value()).isEqualTo(413);
 }

 @Test void actualObserverFactsAreBoundPersistedWhitelistedAndCursorPaged(){var run=create(UUID.randomUUID().toString()).runId();UUID submission=service.requireRun(OPERATOR,run);UUID ai=worker.dispatch(worker.claim());Map<String,Object> event=Map.of("seq",1,"run_id",ai,"type","stage_started","phase","ocr","created_at","2026-10-16T12:00:00Z","data",Map.of("attempt",1,"image_count",2,"error_code","private_lowercase_secret","prompt","PRIVATE PROMPT","url","https://private.example"));String page=json.write(Map.of("items",List.of(event),"next_after",1,"has_more",false));assertThat(observer.importPage(ai,submission,page)).isFalse();assertThat(observer.observerCursor(ai)).isEqualTo(1);String retained=db.queryForObject("SELECT metadata::text FROM submission_events WHERE submission_id=? AND event_type='local_ai_event'",String.class,submission);assertThat(retained).contains("imageCount","attempt").doesNotContain("private_lowercase_secret","PRIVATE PROMPT","private.example");assertThatThrownBy(()->observer.importPage(ai,UUID.randomUUID(),json.write(Map.of("items",List.of(Map.of("seq",2,"run_id",ai,"type","stage_completed","phase","ocr","created_at","2026-10-16T12:00:01Z","data",Map.of())),"next_after",2,"has_more",false)))).isInstanceOf(IllegalArgumentException.class);var result=json.read(json.write(service.events(auth,run,0,1)));assertThat(result.path("items")).hasSize(1);assertThat(result.path("hasMore").asBoolean()).isTrue();long next=result.path("nextAfter").asLong();var rest=json.read(json.write(service.events(auth,run,next,100)));assertThat(rest.toString()).contains("stage_started","ocr").doesNotContain("private_lowercase_secret","PRIVATE PROMPT");}
 @Test void safeProviderCausesSurviveDatabaseAndPublicPageWithoutFinishingTheRun(){
  var run=create(UUID.randomUUID().toString()).runId();UUID submission=service.requireRun(OPERATOR,run),ai=worker.dispatch(worker.claim());observer.track(ai,submission);
  List<Object> records=new ArrayList<>();int seq=0;
  for(String cause:List.of("llm_bad_response","provider_empty_choices","provider_output_truncated")){
   Map<String,Object> data=new LinkedHashMap<>();data.put("code","llm_bad_response");data.put("error_code",cause);data.put("attempt",++seq);data.put("raw_response","PRIVATE MODEL TEXT");data.put("reasoning_content","PRIVATE REASONING");data.put("finish_reason","length");data.put("empty_choices",true);data.put("completion_tokens",32000);data.put("prompt_tokens",42);data.put("reasoning_tokens",31999);data.put("issue_paths",List.of("$.analysis"));data.put("issue_codes",List.of("invalid_stage_response"));data.put("unknown_private_field","PRIVATE VALUE");
   records.add(Map.of("seq",seq,"run_id",ai,"type","model_failed","phase","analysis","created_at","2026-10-16T12:00:00Z","data",data));
  }
  records.add(Map.of("seq",4,"run_id",ai,"type","retry","phase","analysis","created_at","2026-10-16T12:00:01Z","data",Map.of("attempt",4,"code","private_lowercase_secret","error_code","provider_unknown_private")));
  assertThat(observer.importPage(ai,submission,json.write(Map.of("items",records,"next_after",4,"has_more",false)))).isFalse();
  var retained=db.queryForList("SELECT metadata::text FROM submission_events WHERE submission_id=? AND event_type='local_ai_event' ORDER BY id",String.class,submission);
  assertThat(retained).hasSize(4);for(int i=0;i<3;i++){var data=json.read(retained.get(i)).path("data");assertThat(data.propertyNames()).containsExactlyInAnyOrder("code","errorCode","attempt","issueCodes","issuePaths");assertThat(data.path("errorCode").asText()).isEqualTo(List.of("llm_bad_response","provider_empty_choices","provider_output_truncated").get(i));}
  assertThat(json.read(retained.get(3)).path("data").propertyNames()).containsExactly("attempt");
  assertThat(observer.observedTerminal(ai)).isFalse();assertThat(store.row(submission,null,false).status()).isEqualTo("running");assertThat(json.write(observer.observerStatus(submission))).contains("pending");
  var response=rest.exchange("/api/local-demo/runs/"+run+"/events?after=0&limit=100",HttpMethod.GET,new HttpEntity<>(headers(login(),false)),String.class);
  assertThat(response.getStatusCode().value()).isEqualTo(200);assertThat(response.getBody()).contains("llm_bad_response","provider_empty_choices","provider_output_truncated","model_failed","retry").doesNotContain("PRIVATE","private_lowercase_secret","provider_unknown_private","\"finish_reason\"","\"finishReason\"","\"empty_choices\"","\"completion_tokens\"","\"prompt_tokens\"","\"reasoning_tokens\"","\"issue_paths\"","\"issue_codes\"");
 }
 HttpB2bGradingGateway reconciler(com.sun.net.httpserver.HttpServer server){var gateway=new HttpB2bGradingGateway("http://127.0.0.1:"+server.getAddress().getPort(),"observer-test",json,new B2bConfig(true,false,OPERATOR.toString()),store,storage,cropArtifacts,documentValidator);org.springframework.test.util.ReflectionTestUtils.setField(gateway,"events",observer);org.springframework.test.util.ReflectionTestUtils.setField(gateway,"origins",origins);org.springframework.test.util.ReflectionTestUtils.setField(gateway,"transactions",transactions);return gateway;}
 void awaitObserver(java.util.function.BooleanSupplier ready)throws Exception{long deadline=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(4);while(!ready.getAsBoolean()&&System.nanoTime()<deadline)Thread.sleep(10);assertThat(ready.getAsBoolean()).isTrue();}
 @Test void persistedObserverJobSurvivesGatewayRestartAndCapturesLateFinalFacts()throws Exception{var run=create(UUID.randomUUID().toString()).runId();UUID submission=service.requireRun(OPERATOR,run),ai=worker.dispatch(worker.claim());service.events(auth,run,0,100);observer.track(ai,submission);var server=com.sun.net.httpserver.HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);server.start();var calls=new AtomicInteger();server.createContext("/internal/v2/grading/runs/"+ai+"/events",exchange->{calls.incrementAndGet();assertThat(exchange.getRequestMethod()).isEqualTo("GET");assertThat(exchange.getRequestHeaders().getFirst("Authorization")).isEqualTo("Bearer observer-test");var records=List.of(Map.of("seq",1,"run_id",ai,"type","stage_completed","phase","validation","created_at","2026-10-16T12:00:00Z","data",Map.of("valid",true)),Map.of("seq",2,"run_id",ai,"type","completed","phase","validation","created_at","2026-10-16T12:00:01Z","data",Map.of("is_graded",true)));byte[] bytes=json.write(Map.of("items",records,"next_after",2,"has_more",false)).getBytes(java.nio.charset.StandardCharsets.UTF_8);exchange.getResponseHeaders().set("Content-Type","application/json");exchange.sendResponseHeaders(200,bytes.length);exchange.getResponseBody().write(bytes);exchange.close();});var before=reconciler(server);before.stopObservers();var restarted=reconciler(server);try{assertThat(json.write(observer.observerStatus(submission))).contains("pending");restarted.reconcileObservers();awaitObserver(()->db.queryForObject("SELECT completed_at IS NOT NULL FROM local_demo_observer_jobs WHERE ai_run_id=?",Boolean.class,ai));assertThat(observer.observerCursor(ai)).isEqualTo(2);assertThat(json.write(observer.observerStatus(submission))).contains("pending");assertThat(json.write(service.events(auth,run,0,100))).contains("stage_completed","completed","finished");assertThat(calls.get()).isEqualTo(1);verify(gateway,never()).grade(any(),any(),anyLong(),any(),anyList(),any(),any());}finally{restarted.stopObservers();server.stop(0);}}
 @Test void revokedAndExpiredObserversStopWithExplicitIncompleteDiagnostic()throws Exception{var run=create(UUID.randomUUID().toString()).runId();UUID submission=service.requireRun(OPERATOR,run),ai=worker.dispatch(worker.claim());observer.track(ai,submission);db.update("UPDATE school_experts SET enabled=false WHERE user_id=?",OPERATOR);var server=com.sun.net.httpserver.HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);server.start();var calls=new AtomicInteger();server.createContext("/",exchange->{calls.incrementAndGet();exchange.sendResponseHeaders(500,-1);exchange.close();});var actual=reconciler(server);try{actual.reconcileObservers();awaitObserver(()->Boolean.TRUE.equals(db.queryForObject("SELECT incomplete_reason='scope_revoked' FROM local_demo_observer_jobs WHERE ai_run_id=?",Boolean.class,ai)));assertThat(json.write(observer.observerStatus(submission))).contains("incomplete");assertThat(calls.get()).isZero();db.update("UPDATE school_experts SET enabled=true WHERE user_id=?",OPERATOR);var expired=create(UUID.randomUUID().toString()).runId();UUID expiredSubmission=service.requireRun(OPERATOR,expired),expiredAi=worker.dispatch(worker.claim());db.update("INSERT INTO local_demo_observer_jobs(ai_run_id,submission_id,fencing_token,expires_at) SELECT id,submission_id,fencing_token,clock_timestamp()-interval '1 second' FROM grading_runs WHERE id=?",expiredAi);assertThat(json.write(observer.observerStatus(expiredSubmission))).contains("incomplete");assertThat(observer.claimObservers()).isEmpty();assertThat(observer.observerCursor(expiredAi)).isZero();assertThat(calls.get()).isZero();}finally{actual.stopObservers();server.stop(0);}}
 @Test void publicCursorNeverSkipsAnEarlierSourceThatCommitsLater()throws Exception{var run=create(UUID.randomUUID().toString()).runId();UUID submission=service.requireRun(OPERATOR,run);var inserted=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);try(var executor=java.util.concurrent.Executors.newSingleThreadExecutor()){var first=executor.submit(()->transactions.executeWithoutResult(t->{store.event(submission,"upload_ready",OPERATOR,Map.of());inserted.countDown();try{release.await();}catch(InterruptedException e){throw new RuntimeException(e);}}));assertThat(inserted.await(5,java.util.concurrent.TimeUnit.SECONDS)).isTrue();store.event(submission,"queued",OPERATOR,Map.of());var before=json.read(json.write(service.events(auth,run,0,100)));long cursor=before.path("nextAfter").asLong();release.countDown();first.get(5,java.util.concurrent.TimeUnit.SECONDS);var after=json.read(json.write(service.events(auth,run,cursor,100)));assertThat(after.path("items")).hasSize(1);assertThat(after.path("items").get(0).path("type").asText()).isEqualTo("upload_ready");assertThat(after.path("nextAfter").asLong()).isGreaterThan(cursor);var empty=json.read(json.write(service.events(auth,run,after.path("nextAfter").asLong(),100)));assertThat(empty.path("items")).isEmpty();assertThat(empty.path("nextAfter")).isEqualTo(after.path("nextAfter"));}}

 @Test void chunkedMultipartUsesTheSameRouteBoundaries()throws Exception{Login login=login();byte[] padded=Arrays.copyOf(image,5*1024*1024);String boundary="b2b-chunked";var out=new java.io.ByteArrayOutputStream();out.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"task_number\"\r\n\r\n16\r\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));for(String name:List.of("task_image","solution_images")){out.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\""+name+"\"; filename=\"input.png\"\r\nContent-Type: image/png\r\n\r\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));out.write(padded);out.write("\r\n".getBytes(java.nio.charset.StandardCharsets.UTF_8));}out.write(("--"+boundary+"--\r\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));byte[] body=out.toByteArray();var client=java.net.http.HttpClient.newBuilder().version(java.net.http.HttpClient.Version.HTTP_1_1).build();for(String path:List.of("/api/local-demo/runs/manual","/api/submissions/"+UUID.randomUUID()+"/images")){var request=java.net.http.HttpRequest.newBuilder(java.net.URI.create(rest.getRootUri()+path)).header("Cookie","SESSION="+login.session+"; XSRF-TOKEN="+login.csrf).header("X-XSRF-TOKEN",login.csrf).header("Idempotency-Key",UUID.randomUUID().toString()).header("Content-Type","multipart/form-data; boundary="+boundary).POST(java.net.http.HttpRequest.BodyPublishers.ofInputStream(()->new java.io.ByteArrayInputStream(body))).build();var response=client.send(request,java.net.http.HttpResponse.BodyHandlers.ofString());assertThat(response.statusCode()).withFailMessage(response.body()).isEqualTo(path.startsWith("/api/local-demo")?202:413);}}

 @Test void classifiedFailureSurvivesHttpFallbackAndLaterTerminalObservation(){
  var run=create(UUID.randomUUID().toString()).runId();UUID submission=service.requireRun(OPERATOR,run),ai=worker.dispatch(worker.claim());
  observer.recordHttpFailure(ai,submission,json.read("""
   {"failure_category":"model_response","diagnostic_code":602,"reason_code":"provider_output_truncated","phase":"analysis","step":"analysis","attempt":4,"max_attempts":4,"failure_counts":{"model_response":4},"retryable":false,"exhausted":true,"issue_codes":["provider_output_truncated"],"issue_paths":["$.analysis"],"raw_response":"PRIVATE"}
   """));
  store.terminal(store.row(submission,null,false),"failed","ai_error_502");
  var detail=json.read(json.write(service.detail(auth,run)));
  assertThat(detail.path("errorCode").asText()).isEqualTo("ai_error_502");assertThat(detail.path("failure").path("diagnosticCode").asInt()).isEqualTo(602);assertThat(detail.path("failure").path("maxAttempts").asInt()).isEqualTo(4);
  Map<String,Object> data=Map.of("failure_category","model_response","diagnostic_code",607,"reason_code","invalid_analysis","phase","analysis","step","analysis","attempt",4,"max_attempts",4,"exhausted",true);
  var record=Map.of("seq",1,"run_id",ai,"type","failed","phase","analysis","created_at","2026-10-21T12:00:00Z","data",data);
  observer.importPage(ai,submission,json.write(Map.of("items",List.of(record),"next_after",1,"has_more",false)));
  detail=json.read(json.write(service.detail(auth,run)));assertThat(detail.path("failure").path("diagnosticCode").asInt()).isEqualTo(607);
  String projected=json.write(service.events(auth,run,0,100));assertThat(projected).contains("failureCategory","diagnosticCode","maxAttempts","issuePaths").doesNotContain("PRIVATE");
  verify(gateway,never()).grade(any(),any(),anyLong(),any(),anyList(),any(),any());
 }

 @Test void acknowledgeRequiresBothImportedTerminalEventsAndDurableBackendOutcome(){
  var run=create(UUID.randomUUID().toString()).runId();UUID submission=service.requireRun(OPERATOR,run);var claim=worker.claim();UUID ai=worker.dispatch(claim);observer.track(ai,submission);
  var acknowledger=mock(B2bGradingGateway.class);when(acknowledger.acknowledge(any())).thenReturn(true);
  var scheduler=new B2bAiScheduler(db,transactions,worker,mock(org.botai.back.expert.ExpertGradingCoordinator.class),acknowledger,new B2bConfig(true,false,""),true,1);
  try{
   scheduler.acknowledgeCompleted();verify(acknowledger,never()).acknowledge(ai);
   var event=Map.of("seq",1,"run_id",ai,"type","failed","phase","analysis","created_at","2026-10-21T12:00:00Z","data",Map.of("failure_category","model_response","diagnostic_code",602,"reason_code","provider_output_truncated"));
   observer.importPage(ai,submission,json.write(Map.of("items",List.of(event),"next_after",1,"has_more",false)));observer.finishObserver(ai);
   scheduler.acknowledgeCompleted();verify(acknowledger,never()).acknowledge(ai);
   worker.fail(claim,"ai_error_502",true);scheduler.acknowledgeCompleted();verify(acknowledger,times(1)).acknowledge(ai);
   scheduler.acknowledgeCompleted();verify(acknowledger,times(1)).acknowledge(ai);
   assertThat(db.queryForObject("SELECT count(*) FROM local_ai_acknowledgements WHERE run_id=?",Integer.class,ai)).isEqualTo(1);
  }finally{scheduler.close();}
 }

